// =============================================
// Check daily P&L and enforce risk limits
// =============================================
const cfg = $getWorkflowStaticData('global');
const crypto = require('crypto');

const isTestnet = (cfg.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
const apiKey = cfg.BYBIT_API_KEY;
const apiSecret = cfg.BYBIT_API_SECRET;
const MAX_DAILY_LOSS = parseFloat(cfg.MAX_DAILY_LOSS || '3');

async function signedGet(endpoint, params) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const qs = Object.entries(params).map(([k,v]) => `${k}=${v}`).join('&');
  const preSign = timestamp + apiKey + recvWindow + qs;
  const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');
  return this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}${endpoint}?${qs}`,
    headers: {
      'X-BAPI-API-KEY': apiKey, 'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp, 'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    }
  });
}

// Get wallet balance
const balResp = await signedGet.call(this, '/v5/account/wallet-balance', { accountType: 'UNIFIED' });
let totalEquity = 0;
try {
  totalEquity = parseFloat(balResp.result.list[0].totalEquity);
} catch(e) {}

// Get closed P&L for today
const today = new Date();
today.setHours(0, 0, 0, 0);
const startTime = today.getTime().toString();

let dailyPnl = 0;
try {
  const pnlResp = await signedGet.call(this, '/v5/position/closed-pnl', {
    category: 'linear', startTime, limit: '100'
  });
  if (pnlResp.retCode === 0) {
    dailyPnl = (pnlResp.result?.list || []).reduce((sum, p) => sum + parseFloat(p.closedPnl), 0);
  }
} catch(e) {}

// Get unrealized P&L from open positions
let unrealizedPnl = 0;
try {
  const posResp = await signedGet.call(this, '/v5/position/list', {
    category: 'linear', settleCoin: 'USDT'
  });
  if (posResp.retCode === 0) {
    unrealizedPnl = (posResp.result?.list || [])
      .filter(p => parseFloat(p.size) > 0)
      .reduce((sum, p) => sum + parseFloat(p.unrealisedPnl), 0);
  }
} catch(e) {}

const totalDailyPnl = dailyPnl + unrealizedPnl;
const dailyLossPercent = totalEquity > 0 ? Math.abs(Math.min(totalDailyPnl, 0)) / totalEquity * 100 : 0;
const breached = dailyLossPercent >= MAX_DAILY_LOSS;

// Store daily loss for other workflows
const store = $getWorkflowStaticData('global');
store.dailyLoss = dailyLossPercent;
store.lastCheck = Date.now();

// Reset daily loss tracker at midnight
const lastReset = store.lastReset || 0;
if (Date.now() - lastReset > 24 * 60 * 60 * 1000) {
  store.dailyLoss = 0;
  store.lastReset = Date.now();
}

return [{
  json: {
    totalEquity,
    dailyPnl: dailyPnl.toFixed(2),
    unrealizedPnl: unrealizedPnl.toFixed(2),
    totalDailyPnl: totalDailyPnl.toFixed(2),
    dailyLossPercent: dailyLossPercent.toFixed(2),
    maxDailyLoss: MAX_DAILY_LOSS,
    breached,
    baseUrl
  }
}];

// =============================================
// EMERGENCY: Close all positions
// =============================================
const cfg = $getWorkflowStaticData('global');
const data = $input.first().json;
const crypto = require('crypto');

const apiKey = cfg.BYBIT_API_KEY;
const apiSecret = cfg.BYBIT_API_SECRET;

async function signedGet(endpoint, params) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const qs = Object.entries(params).map(([k,v]) => `${k}=${v}`).join('&');
  const preSign = timestamp + apiKey + recvWindow + qs;
  const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');
  return this.helpers.httpRequest({
    method: 'GET',
    url: `${data.baseUrl}${endpoint}?${qs}`,
    headers: {
      'X-BAPI-API-KEY': apiKey, 'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp, 'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    }
  });
}

async function signedPost(endpoint, body) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const bodyStr = JSON.stringify(body);
  const preSign = timestamp + apiKey + recvWindow + bodyStr;
  const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');
  return this.helpers.httpRequest({
    method: 'POST',
    url: `${data.baseUrl}${endpoint}`,
    headers: {
      'X-BAPI-API-KEY': apiKey, 'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp, 'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    },
    body
  });
}

// Cancel all open orders
try {
  await signedPost.call(this, '/v5/order/cancel-all', {
    category: 'linear', settleCoin: 'USDT'
  });
  await signedPost.call(this, '/v5/order/cancel-all', {
    category: 'spot'
  });
} catch(e) {}

// Close all positions
const closedPositions = [];
try {
  const posResp = await signedGet.call(this, '/v5/position/list', {
    category: 'linear', settleCoin: 'USDT'
  });
  if (posResp.retCode === 0) {
    for (const pos of (posResp.result?.list || [])) {
      if (parseFloat(pos.size) === 0) continue;
      const closeSide = pos.side === 'Buy' ? 'Sell' : 'Buy';
      try {
        await signedPost.call(this, '/v5/order/create', {
          category: 'linear',
          symbol: pos.symbol,
          side: closeSide,
          orderType: 'Market',
          qty: pos.size,
          reduceOnly: true
        });
        closedPositions.push(pos.symbol);
      } catch(e) {}
    }
  }
} catch(e) {}

return [{
  json: {
    ...data,
    closedPositions,
    closedCount: closedPositions.length
  }
}];

